import{FakeObservables}from"chrome://resources/ash/common/fake_observables.js";import{getUpdateController,setUseFakeProviders}from"./mojo_interface_provider.js";export const ON_UPDATE_LIST_CHANGED="UpdateObserver_onUpdateListChanged";export class FakeUpdateProvider{constructor(){this.observables=new FakeObservables;this.observePeripheralUpdatesPromise=null;this.inflightUpdate=null;setUseFakeProviders(true);this.registerObservables()}observePeripheralUpdates(remote){this.observePeripheralUpdatesPromise=this.observe(ON_UPDATE_LIST_CHANGED,(firmwareUpdates=>{remote.onUpdateListChanged(firmwareUpdates)}))}fetchInProgressUpdate(){return new Promise((resolve=>resolve({update:this.inflightUpdate})))}prepareForUpdate(deviceId){const controller=getUpdateController();controller.setDeviceIdForUpdateInProgress(deviceId);return new Promise((resolve=>resolve({controller:controller})))}setFakeFirmwareUpdates(firmwareUpdates){this.observables.setObservableData(ON_UPDATE_LIST_CHANGED,[firmwareUpdates])}setInflightUpdate(update){this.inflightUpdate=update}getObservePeripheralUpdatesPromiseForTesting(){return this.observePeripheralUpdatesPromise}triggerDeviceAddedObserver(){this.observables.trigger(ON_UPDATE_LIST_CHANGED)}registerObservables(){this.observables.register(ON_UPDATE_LIST_CHANGED)}reset(){this.observables=new FakeObservables;this.registerObservables()}observe(methodName,callback){return new Promise((resolve=>{this.observables.observe(methodName,callback);this.observables.trigger(methodName);resolve()}))}}